const fleetVcpu = 800;
const costPerVcpuHour = 0.04;
const hoursPerYear = 24 * 365;
const hotFnFleetCpuPct = 0.04;   // 4% of fleet
const saveFraction = 0.5;        // optimization halves it
const engHourlyCost = 120;
const engHours = 3 * 5 * 8;       // 3 weeks

const fleetYearlyCost = fleetVcpu * costPerVcpuHour * hoursPerYear;
const hotFnYearlyCost = fleetYearlyCost * hotFnFleetCpuPct;
const yearlySaved = hotFnYearlyCost * saveFraction;
const engCost = engHours * engHourlyCost;

console.log('fleet $/yr:', Math.round(fleetYearlyCost));
console.log('hot fn $/yr:', Math.round(hotFnYearlyCost));
console.log('saved $/yr:', Math.round(yearlySaved));
console.log('eng cost $:', engCost);
console.log('payback months:', (engCost / yearlySaved * 12).toFixed(1));
console.log('worth it within a year?', yearlySaved >= engCost);
